------clean up party profile that is not used
delete from ui.dashboardfilters where idashboardid=14;
delete from ui.dashboardresultset where idashboardid=14;
delete from ui.dashboard where idashboardid=14;

---set bdynamic true for dashboards loaded in dropdowns
update ui.dashboard set bdynamic=true where imenustructuredesc=577 or imenustructuredesc=536 or imenustructuredesc=510;

