--Main report query Rule efficiency report
UPDATE ui.dashboardquery SET
vcdashboardquery = 'select rp.tdate as "Date", d.vcdecisionname as "Decision", rp.vcclassname as "Class", rp.iruleid as "Rule ID",  r.vcrulename as "Rule Name",
rp.score as "Score", rp.scoretxncount as "Rule Triggered Count", rp.totaltxncount as "Total Txn Count",
round( cast((cast(rp.scoretxncount as float)* 100)/rp.totaltxncount as numeric	),2	) as "Rule Efficiency (%)",
round( cast((cast(rp.override_txncount as float)* 100)/rp.scoretxncount as numeric	),2	) as "False Alert %",
rp.scoretxnvalue / rp.scoretxncount as "Avg Value (Rules Triggered)",
rp.totaltxnvalue / rp.totaltxncount as "Avg Value (Total Txns)",
rp.accounts_affected as "Unique Accounts Triggered",
rp.vpas_affected as "Unique VPAs Affected"
from transactions.rule_performance rp
left join masters.rules r on r.iruleid = rp.iruleid
left join masters.decisions d on d.idecisionid = rp.idecisionid where tdate  between cast(:StartDate as date) and cast(:EndDate as date)-1 and score > 0 
and itenantid=:tenantid;
'::text WHERE
idashboardqueryid = 31;


--Main report query, Master extract
UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
	"Account":"select iaccountid , icustomerid,  vcexternalaccountid, iaccounttypeid, vcifsc, vcaccountproviderid, vcaccountname, dtonboardingdate, dtexpirydate, imcc, bmerchant, bverified, irecordstatus, dtentrydatetime, vcattribs->>''reg_address'' as \\"reg_address\\", vcattribs->>''postal_code'' as \\"postal_code\\", vcattribs->>''merchant_type'' as \\"merchant_type\\", vcattribs->>''registered_mobile'' as \\"registered_mobile\\", vcattribs->>''email'' as \\"email\\" from masters.accounts where itenantid=:tenantid :AttribsForm order by dtentrydatetime desc limit 50000",
	"VPA": "select ivpaid, iaccountid, vcexternaladdressid, vcaddress, iproductid, vcvpaname, bverified, imcc, dtonboardingdate, dtexpirydate, bmerchant, ivpaproviderid, bprofiled, dtfirsttransaction, dtlasttransaction, irecordstatus, dtentrydatetime from masters.vpa where itenantid=:tenantid order by dtentrydatetime desc limit 50000",
	"Customer": "SELECT icustomerid, vcexternalcustid, vccustomername, vccustomertype, vcsalutation, vcverifiedname, vcgender, dtdoidob, dtonboardingdate, vcpostalcode, vcemail, vcregisteredmobile, imcc, vcidentitytype1, vcidentitydetails1, vcidentitytype2, vcidentitydetails2, vcregisteredaddressgeolocation, iadm3, iadm2, iadm1, vccountrycode, vcattribs->>''accountaddress'' as \\"accountaddress\\", vcattribs->>''accountnumber'' as \\"accountnumber\\", vcattribs->>''ifsccode'' as \\"ifscode\\", vcattribs->>''bankname'' as \\"bankname\\", vcattribs->>''settlementmode'' as \\"settlementmode\\", vcattribs->>''accountonboardingdate'' as \\"accountonboardingdate\\", vcattribs->>''address'' as \\"address\\", vcattribs->>''email'' as \\"email\\", vcattribs->>''postalcode'' as \\"postalcode\\", vcattribs->>''annualturnover'' as \\"annualturnover\\", vcattribs->>''registeredmobile'' as \\"registeredmobile\\", vcattribs->>''merchanttype'' as \\"merchanttype\\", vcattribs->>''risk'' as \\"risk\\", irecordstatus, dtentrydatetime FROM masters.customers where itenantid=:tenantid :AttribsForm order by dtentrydatetime desc limit 50000;"
}'::text WHERE
idashboardqueryid = 48;

