---Account wise rule triggered
--Filters:Class
UPDATE ui.dashboardquery SET
vcdashboardquery = 'with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser and mappingtype = ''TransactionClass'')
SELECT ''All'' AS "label", ''All'' AS "value" union all 
(select DISTINCT vcclassname as "label", vcclassname as "value" FROM 
 ui.transactionclasses where bactive=true and (iclassid in (select mappingid from d1) or -1 in (select mappingid from d1))
and itenantid=:tenantid ORDER BY label)'::text WHERE
idashboardqueryid = 34;

update ui.dashboardquery set runonanalytics=false where idashboardqueryid=34;

UPDATE ui.dashboardquery SET
vcdashboardquery = 'SELECT ''All'' AS "label", ''All'' AS "value" union all (select DISTINCT vcdecisionname as "label", vcdecisionname as "value" FROM ui.decisions where bactive=true and itenantid=:tenantid ORDER BY label)'::text WHERE
idashboardqueryid = 35;
update ui.dashboardquery set runonanalytics=false where idashboardqueryid=35;

