---Party Profile
UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "Account": "with recursive profile as ( SELECT pv.iaccountid, pv.tdate, pv.val|| cast(format(''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\", \\"Last Update\\":\\"%s\\"}'' , vcexternalaccountid,  vcaccountname, last_updated) as jsonb) as val FROM profiles.account pv left join masters.accounts v on v.iaccountid = pv.iaccountid where v.itenantid = :tenantid and tdate  between cast(:StartDate as date) and cast(:EndDate as date)-1 and v.vcexternalaccountid =:VpaAddress ), flat ( iaccountid, tdate,  key, value) as ( select  iaccountid, tdate,concat( '''', key), value from profile, jsonb_each(val) \\n union select  iaccountid, tdate,concat(f.key, ''.'', j.key), j.value from flat f, jsonb_each(f.value) j where jsonb_typeof(f.value) = ''object'' ) \\n select cast(json_agg(data) as text) from ( select iaccountid, tdate,jsonb_object_agg((select CASE WHEN (select vccolumnname from profiles.metadata where vcpath = key and vcroot = ''account'') IS NULL THEN key ELSE (select vccolumnname from profiles.metadata where vcpath = key and vcroot = ''account'') END AS  vccolumnname ), value  ) as data from flat where jsonb_typeof(value)<>''object'' group by iaccountid, tdate) a;",
    "VPA": "with recursive profile as ( SELECT pv.ivpaid, pv.tdate, pv.val|| cast(format(''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\", \\"Last Update\\":\\"%s\\"}'' , vcexternaladdressid,  vcvpaname, last_updated) as jsonb) as val FROM profiles.vpa pv left join masters.vpa v on v.ivpaid = pv.ivpaid where v.itenantid=:tenantid and tdate between cast(:StartDate as date) and cast(:EndDate as date)-1 and v.vcexternaladdressid = :VpaAddress ), flat (ivpaid, tdate,key, value) as ( select  ivpaid, tdate, concat( '''', key), value from profile, jsonb_each(val) \\n union select  ivpaid, tdate,concat(f.key, ''.'', j.key), j.value from flat f, jsonb_each(f.value) j where jsonb_typeof(f.value) = ''object'' ) \\n select cast(json_agg(data) as text) from ( select ivpaid, tdate, jsonb_object_agg((select CASE WHEN (select vccolumnname from profiles.metadata where vcpath = key and vcroot = ''vpa'') IS NULL THEN key ELSE (select vccolumnname from profiles.metadata where vcpath = key and vcroot = ''vpa'') END AS  vccolumnname ), value  ) as data from flat where jsonb_typeof(value)<>''object'' group by ivpaid, tdate) a;"
}'::text WHERE
idashboardqueryid = 57;

--Batch Party Profile
UPDATE ui.dashboardquery SET
vcdashboardquery =  E'  {
 	"Account": {
 		"Monthly": " with recursive profile as ( SELECT pv.iaccountid, pv.val|| cast(format(''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\", \\"Last Update\\":\\"%s\\"}'' , vcexternalaccountid,  vcaccountname, last_updated) as jsonb) as val FROM profiles.account_monthly pv left join masters.accounts v on v.iaccountid = pv.iaccountid where v.itenantid = :tenantid and tdate between cast(:StartDate as date) and cast(:EndDate as date)-1 and v.vcexternalaccountid =:Address ), flat ( iaccountid, key, value) as ( select  iaccountid,concat( '''', key), value from profile, jsonb_each(val) \\n union select  iaccountid,concat(f.key, ''.'', j.key), j.value from flat f, jsonb_each(f.value) j where jsonb_typeof(f.value) = ''object'' ) \\n select cast(json_agg(data) as text) from ( select iaccountid,jsonb_object_agg((select CASE WHEN (select vccolumnname from profiles.metadata where vcpath = key and vcroot = ''account_monthly'') IS NULL THEN key ELSE (select vccolumnname from profiles.metadata where vcpath = key and vcroot = ''account_monthly'') END AS  vccolumnname ), value  ) as data from flat where jsonb_typeof(value)<>''object'' group by iaccountid) a;"
 	},
 	"VPA": {
 		"Monthly": "with recursive profile as ( SELECT pv.ivpaid, pv.val|| cast(format(''{\\"Address\\":\\"%s\\",\\"Name\\":\\"%s\\", \\"Last Update\\":\\"%s\\"}'' , vcexternaladdressid,  vcvpaname, last_updated) as jsonb) as val FROM profiles.vpa_monthly pv left join masters.vpa v on v.ivpaid = pv.ivpaid where v.itenantid = :tenantid and tdate between cast(:StartDate as date) and cast(:EndDate as date)-1 and v.vcexternaladdressid = :Address ), flat (ivpaid, key, value) as ( select  ivpaid,concat( '''', key), value from profile, jsonb_each(val) \\n union select  ivpaid,concat(f.key, ''.'', j.key), j.value from flat f, jsonb_each(f.value) j where jsonb_typeof(f.value) = ''object'' ) \\n select cast(json_agg(data) as text) from ( select ivpaid,jsonb_object_agg((select CASE WHEN (select vccolumnname from profiles.metadata where vcpath = key and vcroot = ''vpa_monthly'') IS NULL THEN key ELSE (select vccolumnname from profiles.metadata where vcpath = key and vcroot = ''vpa_monthly'') END AS  vccolumnname ), value  ) as data from flat where jsonb_typeof(value)<>''object'' group by ivpaid) a;"
 	}
 }'::text WHERE
idashboardqueryid = 65;


